const KEY='community-setup-v1';
const people={anna:'Анна',boris:'Борис',vera:'Вера'};
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const person=id=>people[id]||'Без назначения';
const seed=()=>({version:1,tasks:[
 {id:'chairs',title:'Расставить стулья',instructions:'Поставь 24 стула в 4 ряда у сцены. Проход посередине оставь свободным.',assignee:'anna',completed:false,cancelled:false,history:[]},
 {id:'materials',title:'Принести материалы для мастерской',instructions:'Забери бумагу, фломастеры и ножницы из шкафа у входа. Разложи на двух столах справа.',assignee:'boris',completed:true,cancelled:false,history:[]},
 {id:'signs',title:'Разместить указатели',instructions:'Повесь указатели «Зал» у входа и у лестницы. Ленту можно взять на стойке.',assignee:'',completed:false,cancelled:false,history:[]},
 {id:'tea',title:'Подготовить стол для чая',instructions:'Поставь чашки и салфетки на стол у окна. Чай принесёт координатор.',assignee:'anna',completed:false,cancelled:true,history:[]}
]});
function valid(s){return s?.version===1&&Array.isArray(s.tasks)&&new Set(s.tasks.map(t=>t.id)).size===s.tasks.length&&s.tasks.every(t=>typeof t.id==='string'&&typeof t.title==='string'&&t.title.trim()&&typeof t.instructions==='string'&&t.instructions.trim()&&(t.assignee===''||Object.hasOwn(people,t.assignee))&&typeof t.completed==='boolean'&&typeof t.cancelled==='boolean'&&Array.isArray(t.history)&&t.history.every(h=>typeof h.at==='string'&&typeof h.actor==='string'&&typeof h.text==='string'));}
let data,blocked=false;
try{const raw=localStorage.getItem(KEY);data=raw===null?seed():JSON.parse(raw);if(!valid(data))throw Error('invalid');}catch{data={version:1,tasks:[]};blocked=true;}
let role='coordinator',who='anna',filter='active',view=null,returnView=null;
const dialog=$('#sheet');
function notify(text){$('#notice').textContent=text;}
const actor=()=>role==='coordinator'?'Координатор':`Волонтёр ${person(who)}`;
function canChange(t){return !blocked&&!t.cancelled&&(role==='coordinator'||t.assignee===who);}
function persist(next){if(blocked)throw Error('Данные недоступны. Используй явный сброс демоданных.');if($('#fail').checked){$('#fail').checked=false;throw Error('Однократный демонстрационный отказ записи. Имитация снята; повтори сохранение в этой форме.');}localStorage.setItem(KEY,JSON.stringify(next));data=next;}
function error(message){const target=$('#action-error')||$('#form-error');if(target)target.textContent=message;else notify(message);}
function mutate(id,update,text){try{const next=structuredClone(data);const t=next.tasks.find(t=>t.id===id);if(!t)throw Error('Поручение не найдено.');update(t);t.history.unshift({at:new Date().toISOString(),actor:actor(),text});persist(next);render();detail(id);notify('Сохранено в этом браузере.');}catch(e){error('Изменения не сохранены; прежние данные не изменены. '+(e.message||'Ошибка записи в этом браузере.'));}}
function badge(t){return `<span class="badge ${t.cancelled?'cancelled':t.completed?'done':''}">${t.cancelled?'Отменено':t.completed?'Готово':'В работе'}</span>`;}
function render(){
 $('#context').textContent=role==='coordinator'?'Контекст: координатор':`Контекст: волонтёр ${person(who)}`;
 $('#person-label').hidden=role!=='volunteer';
 $('#fatal').className=blocked?'error':'';$('#fatal').textContent=blocked?'Не удалось прочитать сохранённые данные. Изменения заблокированы; исходное хранилище не перезаписано. Для демонстрации используй «Сбросить демоданные» в верхней панели.':'';
 $('#create').hidden=role!=='coordinator';$('#create').disabled=blocked;
 $('#list-title').textContent=role==='coordinator'?'Поручения':'Мои поручения';
 const active=data.tasks.filter(t=>!t.cancelled),done=active.filter(t=>t.completed).length;
 $('#overview').innerHTML=role==='coordinator'?`<div class="summary"><div class="summary-content"><strong>${done} из ${active.length}</strong><p>${active.length?'активных поручений готово':'Нет активных задач'}</p><div class="progress" aria-hidden="true"><span style="width:${active.length?done/active.length*100:0}%"></span></div></div><p>${active.filter(t=>!t.assignee).length}<br>без назначения</p></div>`:'';
 const filters=role==='coordinator'?[['active','Все активные'],['pending','В работе'],['done','Готовые'],['cancelled','Отменённые']]:[['active','В работе'],['done','Готовые'],['cancelled','Отменённые']];
 const belongs=t=>role==='coordinator'||t.assignee===who;
 const matches=(t,f)=>f==='cancelled'?t.cancelled:!t.cancelled&&(f==='done'?t.completed:f==='pending'||role==='volunteer'?!t.completed:true);
 $('#filters').innerHTML=filters.map(([id,label])=>`<button type="button" data-filter="${id}" aria-pressed="${filter===id}">${label} · ${data.tasks.filter(t=>belongs(t)&&matches(t,id)).length}</button>`).join('');
 const list=data.tasks.filter(t=>belongs(t)&&matches(t,filter));
 $('#tasks').innerHTML=list.length?list.map(t=>`<button type="button" class="task" data-task="${esc(t.id)}"><span class="text"><h3>${esc(t.title)}</h3><p class="meta">${esc(person(t.assignee))}</p><p>${badge(t)}</p></span><span class="arrow" aria-hidden="true">›</span></button>`).join(''):`<div class="empty"><h3>Здесь пока нет поручений</h3><p>${role==='volunteer'?'В этой группе нет твоих задач. Если ожидаешь поручение, уточни назначение у координатора.':'Измени фильтр или создай новое поручение.'}</p></div>`;
}
function open(html,type,id=null){view={type,id};$('#sheet-body').innerHTML=html;if(!dialog.open)dialog.showModal();$('#sheet-body').scrollTop=0;}
function close(){dialog.close();view=null;returnView=null;}
function top(title){return `<div class="sheet-top"><h2 id="sheet-title">${esc(title)}</h2><button type="button" data-action="close" aria-label="Закрыть детали">Закрыть</button></div>`;}
function detail(id){const t=data.tasks.find(t=>t.id===id);if(!t||(role==='volunteer'&&t.assignee!==who)){close();return;}open(`${top(t.title)}${badge(t)}<p><span class="label">Ответственный</span><br><strong>${esc(person(t.assignee))}</strong></p><div class="instruction">${esc(t.instructions)}</div>${t.cancelled?`<p class="cancel-info">Поручение отменено. Сохранённая готовность: <strong>${t.completed?'Готово':'В работе'}</strong>. При восстановлении эта отметка вернётся.</p>`:''}<div id="action-error" class="error" role="alert"></div><div class="actions">${canChange(t)?`<button type="button" class="primary" data-action="toggle">${t.completed?'Вернуть в работу':'Отметить готовым'}</button>`:''}${role==='coordinator'?`<button type="button" data-action="edit" ${blocked?'disabled':''}>Изменить</button>${t.cancelled?`<button type="button" class="primary" data-action="restore" ${blocked?'disabled':''}>Восстановить</button>`:`<button type="button" class="danger" data-action="cancel-task" ${blocked?'disabled':''}>Отменить поручение</button>`}`:''}</div><h3>История изменений</h3>${t.history.length?`<ol class="history">${t.history.map(h=>`<li><time>${esc(new Date(h.at).toLocaleString('ru-RU'))} · ${esc(h.actor)}</time>${esc(h.text)}</li>`).join('')}</ol>`:'<p class="label">Это демонстрационное поручение. Изменений ещё нет.</p>'}`,'detail',id);}
function form(id=null){const t=data.tasks.find(t=>t.id===id);returnView=id?{type:'detail',id}:null;open(`${top(id?'Изменить поручение':'Новое поручение')}<form id="task-form" novalidate><label for="title">Название</label><input id="title" name="title" value="${esc(t?.title||'')}" required><label for="instructions">Что нужно сделать</label><textarea id="instructions" name="instructions" required>${esc(t?.instructions||'')}</textarea><label for="assignee">Ответственный</label><select id="assignee" name="assignee"><option value="">Без назначения</option>${Object.entries(people).map(([key,name])=>`<option value="${key}" ${t?.assignee===key?'selected':''}>${name}</option>`).join('')}</select>${t?'<p class="label">Изменение ответственного сохраняет текущую готовность.</p>':''}<div id="form-error" class="error" role="alert"></div><div class="actions"><button type="submit" class="primary">Сохранить</button><button type="button" data-action="back">Отмена</button></div></form>`,'form',id);$('#title').focus();}
function back(){if(returnView){const id=returnView.id;returnView=null;detail(id);}else close();}
function confirmCancel(id){const t=data.tasks.find(t=>t.id===id);returnView={type:'detail',id};open(`${top('Отменить поручение?')}<p><strong>${esc(t.title)}</strong></p><p>Поручение уйдёт из текущих. Назначение, инструкция и готовность сохранятся. Его можно будет восстановить из «Отменённых».</p><div id="action-error" class="error" role="alert"></div><div class="actions"><button type="button" class="danger" data-action="confirm-cancel">Отменить поручение</button><button type="button" data-action="back">Оставить</button></div>`,'confirm',id);}
$('#filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;render();}});
$('#tasks').addEventListener('click',e=>{const b=e.target.closest('[data-task]');if(b)detail(b.dataset.task);});
$('#create').onclick=()=>{if(role==='coordinator'&&!blocked)form();};
$('#sheet-body').addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;const id=view?.id,t=data.tasks.find(t=>t.id===id);if(a==='close'||a==='back'){if(view.type==='detail')close();else back();return;}if(a==='toggle'&&t&&canChange(t)){mutate(id,t=>t.completed=!t.completed,`Готовность: ${t.completed?'Готово → В работе':'В работе → Готово'}`);return;}if(role!=='coordinator'||blocked)return;if(a==='edit')form(id);if(a==='cancel-task')confirmCancel(id);if(a==='confirm-cancel'&&!t.cancelled)mutate(id,t=>t.cancelled=true,'Поручение: Активно → Отменено. Назначение и готовность сохранены.');if(a==='restore'&&t.cancelled)mutate(id,t=>t.cancelled=false,`Поручение: Отменено → Активно. Готовность: ${t.completed?'Готово':'В работе'}.`);});
$('#sheet-body').addEventListener('submit',e=>{if(e.target.id!=='task-form')return;e.preventDefault();if(role!=='coordinator'||blocked)return;const fd=new FormData(e.target),title=fd.get('title').trim(),instructions=fd.get('instructions').trim(),assignee=fd.get('assignee');$('#title').setAttribute('aria-invalid',String(!title));$('#instructions').setAttribute('aria-invalid',String(!instructions));if(!title||!instructions){error('Заполни название и инструкцию. Ввод сохранён в форме.');(!title?$('#title'):$('#instructions')).focus();return;}
 try{const next=structuredClone(data),id=view.id;if(id){const t=next.tasks.find(t=>t.id===id);const changes=[];if(t.title!==title)changes.push(`Название: «${t.title}» → «${title}»`);if(t.instructions!==instructions)changes.push(`Инструкция: «${t.instructions}» → «${instructions}»`);if(t.assignee!==assignee)changes.push(`Ответственный: ${person(t.assignee)} → ${person(assignee)}`);if(!changes.length){detail(id);returnView=null;notify('Изменений нет.');return;}Object.assign(t,{title,instructions,assignee});t.history.unshift({at:new Date().toISOString(),actor:actor(),text:changes.join('\n')});}else{next.tasks.push({id:crypto.randomUUID(),title,instructions,assignee,completed:false,cancelled:false,history:[{at:new Date().toISOString(),actor:actor(),text:`Создано поручение. Ответственный: ${person(assignee)}.`}]});}persist(next);render();returnView=null;if(id)detail(id);else close();notify('Сохранено в этом браузере.');}catch(e){error('Изменения не сохранены. Ввод остаётся в форме; прежние данные не изменены. '+(e.message||'Ошибка записи в этом браузере.'));}});
dialog.addEventListener('cancel',e=>{e.preventDefault();if(view?.type==='detail')close();else back();});
$('#role').onchange=e=>{close();role=e.target.value;filter='active';notify('');render();};
$('#person').onchange=e=>{close();who=e.target.value;filter='active';notify('');render();};
$('#reset').onclick=()=>{if(!window.confirm('Сбросить все изменения этого кандидата и вернуть демоданные? Это нельзя отменить.'))return;try{const next=seed();if($('#fail').checked)throw Error('Отключи имитацию отказа записи перед сбросом.');localStorage.setItem(KEY,JSON.stringify(next));data=next;blocked=false;filter='active';close();render();notify('Демоданные восстановлены в этом браузере.');}catch(e){notify(e.message||'Не удалось сбросить данные.');}};
render();
